def update_reservation_passengers(reservation_id: str, passengers: list):
    """
    Update the passenger information of a reservation.

    Args:
        reservation_id: The reservation ID, such as 'ZFA04Y'.
        passengers: A list of passenger objects. Each MUST use the keys 'first_name', 'last_name', and 'dob' (date of birth, 'YYYY-MM-DD'). Example: {"first_name": "Mia", "last_name": "Li", "dob": "1990-04-05"}. Do NOT use 'date_of_birth'. The number of passengers MUST equal the number already on the reservation (you may change their details but NOT add or remove passengers).
    """
    def _norm_passengers(paxs):
        # Map a wrong date-of-birth key to the required 'dob'. Fires only when
        # 'dob' is absent, so a correctly-shaped passenger passes through unchanged.
        if not isinstance(paxs, list):
            return paxs
        out = []
        for p in paxs:
            if isinstance(p, dict):
                p = dict(p)
                if "dob" not in p:
                    for k in ("date_of_birth", "dateOfBirth", "birth_date", "birthdate", "dateofbirth", "DOB"):
                        if k in p:
                            p["dob"] = p[k]
                            break
            out.append(p)
        return out

    passengers = _norm_passengers(passengers)

    result = env_update_reservation_passengers(reservation_id=reservation_id, passengers=passengers)

    # Recovery only on the count-mismatch failure (success returns a reservation
    # dict). Tell the agent the EXACT required count from the live reservation.
    if isinstance(result, str) and "passengers does not match" in result:
        required = None
        try:
            res = env_get_reservation_details(reservation_id=reservation_id)
            if isinstance(res, dict) and isinstance(res.get("passengers"), list):
                required = len(res["passengers"])
        except Exception:
            required = None
        got = len(passengers) if isinstance(passengers, list) else "unknown"
        if required is not None:
            return (result + f". This reservation has EXACTLY {required} passenger(s); you passed {got}. "
                    f"The number of passengers cannot be changed — re-call with exactly {required} passenger "
                    f"object(s), editing their details only.")
        return (result + ". The number of passengers cannot be changed; re-call with the same number of "
                "passenger objects already on the reservation.")

    return result
